// DOM tree data structures
use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug, Clone)]
pub enum NodeData {
    Document,
    Doctype {
        name: String,
        public_id: String,
        system_id: String,
    },
    Element {
        name: String,
        attrs: RefCell<Vec<(String, String)>>,
    },
    Text {
        content: RefCell<String>,
    },
    Comment {
        content: String,
    },
    ProcessingInstruction {
        target: String,
        data: String,
    },
}

pub struct Node {
    pub data: NodeData,
    pub parent: RefCell<Option<Weak<Node>>>,
    pub children: RefCell<Vec<Rc<Node>>>,
}

impl Node {
    pub fn new(data: NodeData) -> Rc<Self> {
        Rc::new(Node {
            data,
            parent: RefCell::new(None),
            children: RefCell::new(Vec::new()),
        })
    }

    pub fn append(parent: &Rc<Node>, child: Rc<Node>) {
        *child.parent.borrow_mut() = Some(Rc::downgrade(parent));
        parent.children.borrow_mut().push(child);
    }

    pub fn insert_before(parent: &Rc<Node>, child: Rc<Node>, before_idx: usize) {
        *child.parent.borrow_mut() = Some(Rc::downgrade(parent));
        parent.children.borrow_mut().insert(before_idx, child);
    }

    pub fn remove(node: &Rc<Node>) {
        let parent_rc = {
            let p = node.parent.borrow();
            p.as_ref().and_then(|w| w.upgrade())
        };
        if let Some(parent) = parent_rc {
            let mut children = parent.children.borrow_mut();
            if let Some(pos) = children.iter().position(|n| Rc::ptr_eq(n, node)) {
                children.remove(pos);
            }
        }
        *node.parent.borrow_mut() = None;
    }

    pub fn get_attr(&self, name: &str) -> Option<String> {
        if let NodeData::Element { attrs, .. } = &self.data {
            for (k, v) in attrs.borrow().iter() {
                if k == name {
                    return Some(v.clone());
                }
            }
        }
        None
    }

    pub fn set_attr(&self, name: &str, value: &str) {
        if let NodeData::Element { attrs, .. } = &self.data {
            let mut attrs = attrs.borrow_mut();
            for (k, v) in attrs.iter_mut() {
                if k == name {
                    *v = value.to_string();
                    return;
                }
            }
            attrs.push((name.to_string(), value.to_string()));
        }
    }

    pub fn tag_name(&self) -> Option<String> {
        if let NodeData::Element { name, .. } = &self.data {
            Some(name.clone())
        } else {
            None
        }
    }

    pub fn is_element(&self) -> bool {
        matches!(self.data, NodeData::Element { .. })
    }

    pub fn is_text(&self) -> bool {
        matches!(self.data, NodeData::Text { .. })
    }
}

pub fn extract_text(node: &Rc<Node>, output: &mut String) {
    match &node.data {
        NodeData::Text { content } => {
            output.push_str(&content.borrow());
        }
        _ => {
            for child in node.children.borrow().iter() {
                extract_text(child, output);
            }
        }
    }
}

/// Extract text walking each text node and invoking callback with `is_whitespace_only`.
pub fn walk_text_nodes<F: FnMut(&str)>(node: &Rc<Node>, cb: &mut F) {
    match &node.data {
        NodeData::Text { content } => {
            cb(&content.borrow());
        }
        _ => {
            for child in node.children.borrow().iter() {
                walk_text_nodes(child, cb);
            }
        }
    }
}
