// Simple HTML parser building a DOM tree.
// Handles tags, attributes, comments, DOCTYPEs, text, entities, implicit html/head/body wrapping,
// void elements, and raw text elements (script/style).

use std::cell::RefCell;
use std::rc::Rc;
use crate::dom::{Node, NodeData};
use crate::entities;

pub fn is_void_element(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "area" | "base" | "br" | "col" | "embed" | "hr" | "img" | "input"
            | "keygen" | "link" | "meta" | "param" | "source" | "track" | "wbr"
    )
}

fn is_raw_text(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "script" | "style" | "xmp" | "iframe" | "noembed" | "noframes" | "noscript" | "plaintext"
    )
}

fn is_escapable_raw(name: &str) -> bool {
    matches!(name.to_ascii_lowercase().as_str(), "textarea" | "title")
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
    open_stack: Vec<Rc<Node>>,
    document: Rc<Node>,
    html_elem: Option<Rc<Node>>,
    head_elem: Option<Rc<Node>>,
    body_elem: Option<Rc<Node>>,
    head_closed: bool,
}

pub fn parse(input: &str) -> Rc<Node> {
    let mut parser = Parser {
        input: input.as_bytes(),
        pos: 0,
        open_stack: Vec::new(),
        document: Node::new(NodeData::Document),
        html_elem: None,
        head_elem: None,
        body_elem: None,
        head_closed: false,
    };
    parser.parse_document();
    parser.document
}

impl<'a> Parser<'a> {
    fn peek(&self, offset: usize) -> Option<u8> {
        self.input.get(self.pos + offset).copied()
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.input[self.pos..].len() >= s.len() && self.input[self.pos..self.pos + s.len()].eq_ignore_ascii_case(s)
    }

    fn starts_with_cs(&self, s: &[u8]) -> bool {
        self.input[self.pos..].starts_with(s)
    }

    fn parse_document(&mut self) {
        loop {
            if self.pos >= self.input.len() {
                break;
            }
            if self.starts_with_cs(b"<!--") {
                self.parse_comment();
            } else if self.starts_with(b"<!doctype") || self.starts_with_cs(b"<!") {
                self.parse_doctype_or_bogus();
            } else if self.starts_with_cs(b"<?") {
                self.parse_processing_instruction();
            } else if self.peek(0) == Some(b'<') && self.peek(1) == Some(b'/') {
                self.parse_end_tag();
            } else if self.peek(0) == Some(b'<') && self.is_tag_start(1) {
                self.parse_start_tag();
            } else {
                self.parse_text();
            }
        }
    }

    fn is_tag_start(&self, offset: usize) -> bool {
        matches!(self.peek(offset), Some(c) if c.is_ascii_alphabetic())
    }

    fn parse_comment(&mut self) {
        // <!-- ... -->
        self.pos += 4;
        let start = self.pos;
        while self.pos < self.input.len() {
            if self.starts_with_cs(b"-->") {
                let content = String::from_utf8_lossy(&self.input[start..self.pos]).into_owned();
                self.pos += 3;
                self.append_to_current(Node::new(NodeData::Comment { content }));
                return;
            }
            self.pos += 1;
        }
        // EOF in comment: append whatever we have
        let content = String::from_utf8_lossy(&self.input[start..]).into_owned();
        self.append_to_current(Node::new(NodeData::Comment { content }));
    }

    fn parse_doctype_or_bogus(&mut self) {
        if self.starts_with(b"<!doctype") {
            self.pos += 9; // "<!doctype".len()
            self.skip_whitespace();
            let name_start = self.pos;
            while self.pos < self.input.len() {
                let c = self.input[self.pos];
                if c == b'>' || c.is_ascii_whitespace() {
                    break;
                }
                self.pos += 1;
            }
            let name = String::from_utf8_lossy(&self.input[name_start..self.pos])
                .to_ascii_lowercase();
            // Skip to '>'
            while self.pos < self.input.len() && self.input[self.pos] != b'>' {
                self.pos += 1;
            }
            if self.pos < self.input.len() {
                self.pos += 1; // consume '>'
            }
            // Attach doctype to document
            self.document.children.borrow_mut().push(Node::new(NodeData::Doctype {
                name,
                public_id: String::new(),
                system_id: String::new(),
            }));
        } else {
            // Bogus: skip to '>'
            self.pos += 2;
            while self.pos < self.input.len() && self.input[self.pos] != b'>' {
                self.pos += 1;
            }
            if self.pos < self.input.len() {
                self.pos += 1;
            }
        }
    }

    fn parse_processing_instruction(&mut self) {
        self.pos += 2; // <?
        let start = self.pos;
        while self.pos < self.input.len() {
            if self.input[self.pos] == b'>' {
                let content = String::from_utf8_lossy(&self.input[start..self.pos]).into_owned();
                self.pos += 1;
                // Just ignore PIs (not emitted in output) - but treat as comment
                // In HTML5 parsing, PIs become comments
                let comment_content = format!("?{}", content);
                self.append_to_current(Node::new(NodeData::Comment { content: comment_content }));
                return;
            }
            self.pos += 1;
        }
    }

    fn parse_end_tag(&mut self) {
        self.pos += 2; // </
        let name_start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'>' || c.is_ascii_whitespace() || c == b'/' {
                break;
            }
            self.pos += 1;
        }
        let name = String::from_utf8_lossy(&self.input[name_start..self.pos]).to_ascii_lowercase();
        // Skip to '>'
        while self.pos < self.input.len() && self.input[self.pos] != b'>' {
            self.pos += 1;
        }
        if self.pos < self.input.len() {
            self.pos += 1;
        }
        if name.is_empty() {
            return;
        }
        // Close element with matching name in stack (pop everything above it)
        let mut found = None;
        for (i, n) in self.open_stack.iter().enumerate().rev() {
            if let Some(tn) = n.tag_name() {
                if tn == name {
                    found = Some(i);
                    break;
                }
            }
        }
        if let Some(i) = found {
            self.open_stack.truncate(i);
            if name == "head" {
                self.head_closed = true;
            }
        }
    }

    fn parse_start_tag(&mut self) {
        self.pos += 1; // <
        let name_start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'>' || c == b'/' || c.is_ascii_whitespace() {
                break;
            }
            self.pos += 1;
        }
        let tag_name = String::from_utf8_lossy(&self.input[name_start..self.pos])
            .to_ascii_lowercase();

        // Parse attributes
        let mut attrs: Vec<(String, String)> = Vec::new();
        let mut self_closing = false;
        loop {
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                break;
            }
            let c = self.input[self.pos];
            if c == b'>' {
                self.pos += 1;
                break;
            }
            if c == b'/' {
                self.pos += 1;
                if self.peek(0) == Some(b'>') {
                    self_closing = true;
                    self.pos += 1;
                    break;
                }
                continue;
            }
            // Parse attribute
            if let Some((name, value)) = self.parse_attribute() {
                if !name.is_empty() {
                    // Avoid duplicates: first one wins
                    if !attrs.iter().any(|(k, _)| k == &name) {
                        attrs.push((name, value));
                    }
                }
            } else {
                self.pos += 1;
            }
        }

        self.handle_start_tag(&tag_name, attrs, self_closing);
    }

    fn handle_start_tag(&mut self, tag_name: &str, attrs: Vec<(String, String)>, self_closing: bool) {
        // Implicit html/head/body
        match tag_name {
            "html" => {
                // open html
                let node = Node::new(NodeData::Element {
                    name: tag_name.to_string(),
                    attrs: RefCell::new(attrs),
                });
                if self.html_elem.is_none() {
                    Node::append(&self.document, node.clone());
                    self.html_elem = Some(node.clone());
                    self.open_stack.push(node);
                }
                return;
            }
            "head" => {
                self.ensure_html();
                if self.head_elem.is_none() {
                    let node = Node::new(NodeData::Element {
                        name: tag_name.to_string(),
                        attrs: RefCell::new(attrs),
                    });
                    Node::append(self.html_elem.as_ref().unwrap(), node.clone());
                    self.head_elem = Some(node.clone());
                    // Close any body
                    self.open_stack.retain(|n| n.tag_name().as_deref() != Some("body"));
                    self.open_stack.push(node);
                }
                return;
            }
            "body" => {
                self.ensure_html();
                // close head if open
                if !self.head_closed {
                    self.head_closed = true;
                    self.open_stack.retain(|n| n.tag_name().as_deref() != Some("head"));
                }
                if self.body_elem.is_none() {
                    let node = Node::new(NodeData::Element {
                        name: tag_name.to_string(),
                        attrs: RefCell::new(attrs),
                    });
                    Node::append(self.html_elem.as_ref().unwrap(), node.clone());
                    self.body_elem = Some(node.clone());
                    self.open_stack.push(node);
                }
                return;
            }
            _ => {}
        }

        // Auto-insert html/head/body as needed
        let is_head_content = matches!(
            tag_name,
            "base" | "basefont" | "bgsound" | "link" | "meta" | "noscript" | "script"
                | "style" | "template" | "title"
        );

        self.ensure_html();
        if is_head_content && !self.head_closed && self.body_elem.is_none() {
            self.ensure_head();
        } else {
            if !self.head_closed {
                // Close head implicitly
                self.head_closed = true;
                self.open_stack.retain(|n| n.tag_name().as_deref() != Some("head"));
            }
            self.ensure_body();
        }

        let node = Node::new(NodeData::Element {
            name: tag_name.to_string(),
            attrs: RefCell::new(attrs),
        });
        let parent = self.current_parent();
        Node::append(&parent, node.clone());

        if is_void_element(tag_name) {
            // Don't push; void elements have no content
            return;
        }

        if self_closing && !is_void_element(tag_name) {
            // In HTML5, self-closing on non-void elements is ignored; but we'll allow it to not push
            // Actually, html5ever keeps it open. To match behavior, don't self-close.
        }

        // Raw text / escapable raw text elements consume content literally
        if is_raw_text(tag_name) || is_escapable_raw(tag_name) {
            // Parse until </tag>
            let escapable = is_escapable_raw(tag_name);
            let content = self.parse_raw_text(tag_name);
            let text_node = Node::new(NodeData::Text {
                content: RefCell::new(if escapable { decode_entities(&content) } else { content }),
            });
            Node::append(&node, text_node);
            return;
        }

        self.open_stack.push(node);
    }

    fn parse_raw_text(&mut self, tag_name: &str) -> String {
        let mut result = String::new();
        let lower = tag_name.to_ascii_lowercase();
        loop {
            if self.pos >= self.input.len() {
                break;
            }
            if self.input[self.pos] == b'<'
                && self.peek(1) == Some(b'/')
                && self.starts_with(format!("</{}", lower).as_bytes())
            {
                // Check that the character after tag name is whitespace or > or /
                let check_pos = self.pos + 2 + lower.len();
                if check_pos <= self.input.len() {
                    let c = self.input.get(check_pos).copied();
                    if matches!(c, Some(b'>') | Some(b'/')) || c.map_or(false, |b| b.is_ascii_whitespace()) {
                        // Consume end tag
                        self.pos = check_pos;
                        while self.pos < self.input.len() && self.input[self.pos] != b'>' {
                            self.pos += 1;
                        }
                        if self.pos < self.input.len() {
                            self.pos += 1;
                        }
                        break;
                    }
                }
            }
            result.push(self.input[self.pos] as char);
            self.pos += 1;
        }
        // Need to handle UTF-8 properly. Let me redo with bytes -> String
        result
    }

    fn parse_attribute(&mut self) -> Option<(String, String)> {
        let name_start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'=' || c == b'>' || c == b'/' || c.is_ascii_whitespace() {
                break;
            }
            self.pos += 1;
        }
        if self.pos == name_start {
            return None;
        }
        let name = String::from_utf8_lossy(&self.input[name_start..self.pos])
            .to_ascii_lowercase();
        self.skip_whitespace();
        let mut value = String::new();
        if self.peek(0) == Some(b'=') {
            self.pos += 1;
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                return Some((name, value));
            }
            let c = self.input[self.pos];
            if c == b'"' || c == b'\'' {
                let quote = c;
                self.pos += 1;
                let val_start = self.pos;
                while self.pos < self.input.len() && self.input[self.pos] != quote {
                    self.pos += 1;
                }
                value = String::from_utf8_lossy(&self.input[val_start..self.pos]).into_owned();
                if self.pos < self.input.len() {
                    self.pos += 1; // consume closing quote
                }
                value = decode_entities(&value);
            } else {
                let val_start = self.pos;
                while self.pos < self.input.len() {
                    let c = self.input[self.pos];
                    if c.is_ascii_whitespace() || c == b'>' {
                        break;
                    }
                    self.pos += 1;
                }
                value = String::from_utf8_lossy(&self.input[val_start..self.pos]).into_owned();
                value = decode_entities(&value);
            }
        }
        Some((name, value))
    }

    fn parse_text(&mut self) {
        let start = self.pos;
        while self.pos < self.input.len() && self.input[self.pos] != b'<' {
            self.pos += 1;
        }
        let raw = &self.input[start..self.pos];
        let text = decode_entities(&String::from_utf8_lossy(raw));
        if text.is_empty() {
            return;
        }
        // Check: if outside body, skip whitespace-only text; else include
        // For simplicity, always include. We need to make sure text goes into body.
        if self.body_elem.is_none() && self.html_elem.is_none() {
            // Leading text before any tag - if whitespace, skip; else, start body
            if text.chars().all(|c| c.is_ascii_whitespace()) {
                return;
            }
        }
        // If we're before body and there's non-whitespace text, need body
        if self.head_closed || self.body_elem.is_some() || text.chars().any(|c| !c.is_ascii_whitespace()) {
            self.ensure_html();
            if !self.head_closed {
                // If text is all whitespace, may go to head... Let's just skip
                if text.chars().all(|c| c.is_ascii_whitespace()) {
                    return;
                }
                self.head_closed = true;
                self.open_stack.retain(|n| n.tag_name().as_deref() != Some("head"));
            }
            self.ensure_body();
            let parent = self.current_parent();
            // Try to merge with previous text node
            {
                let children = parent.children.borrow();
                if let Some(last) = children.last() {
                    if let NodeData::Text { content } = &last.data {
                        content.borrow_mut().push_str(&text);
                        return;
                    }
                }
            }
            Node::append(&parent, Node::new(NodeData::Text {
                content: RefCell::new(text),
            }));
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn ensure_html(&mut self) {
        if self.html_elem.is_none() {
            let node = Node::new(NodeData::Element {
                name: "html".to_string(),
                attrs: RefCell::new(Vec::new()),
            });
            Node::append(&self.document, node.clone());
            self.html_elem = Some(node.clone());
            self.open_stack.push(node);
        }
    }

    fn ensure_head(&mut self) {
        self.ensure_html();
        if self.head_elem.is_none() {
            let node = Node::new(NodeData::Element {
                name: "head".to_string(),
                attrs: RefCell::new(Vec::new()),
            });
            Node::append(self.html_elem.as_ref().unwrap(), node.clone());
            self.head_elem = Some(node.clone());
            self.open_stack.push(node);
        }
    }

    fn ensure_body(&mut self) {
        self.ensure_html();
        if self.head_elem.is_none() {
            // Auto-create head (empty)
            let head = Node::new(NodeData::Element {
                name: "head".to_string(),
                attrs: RefCell::new(Vec::new()),
            });
            Node::append(self.html_elem.as_ref().unwrap(), head.clone());
            self.head_elem = Some(head);
            self.head_closed = true;
        }
        if self.body_elem.is_none() {
            let node = Node::new(NodeData::Element {
                name: "body".to_string(),
                attrs: RefCell::new(Vec::new()),
            });
            Node::append(self.html_elem.as_ref().unwrap(), node.clone());
            self.body_elem = Some(node.clone());
            self.open_stack.push(node);
        }
    }

    fn current_parent(&self) -> Rc<Node> {
        for n in self.open_stack.iter().rev() {
            return n.clone();
        }
        self.document.clone()
    }

    fn append_to_current(&mut self, node: Rc<Node>) {
        let parent = self.current_parent();
        Node::append(&parent, node);
    }
}

pub fn decode_entities(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'&' {
            // Try to decode
            if i + 1 < bytes.len() && bytes[i + 1] == b'#' {
                // Numeric entity
                let mut j = i + 2;
                let hex = j < bytes.len() && (bytes[j] == b'x' || bytes[j] == b'X');
                if hex {
                    j += 1;
                }
                let num_start = j;
                while j < bytes.len() {
                    let b = bytes[j];
                    if hex && b.is_ascii_hexdigit() {
                        j += 1;
                    } else if !hex && b.is_ascii_digit() {
                        j += 1;
                    } else {
                        break;
                    }
                }
                if j > num_start {
                    let num_str = std::str::from_utf8(&bytes[num_start..j]).unwrap_or("");
                    let code = if hex {
                        u32::from_str_radix(num_str, 16).ok()
                    } else {
                        num_str.parse::<u32>().ok()
                    };
                    if let Some(code) = code {
                        if let Some(ch) = char::from_u32(code) {
                            out.push(ch);
                            if j < bytes.len() && bytes[j] == b';' {
                                j += 1;
                            }
                            i = j;
                            continue;
                        }
                    }
                }
            } else if i + 1 < bytes.len() && bytes[i + 1].is_ascii_alphabetic() {
                // Named entity
                let mut j = i + 1;
                while j < bytes.len() && (bytes[j].is_ascii_alphanumeric()) {
                    j += 1;
                }
                let name = std::str::from_utf8(&bytes[i + 1..j]).unwrap_or("");
                if let Some(replacement) = entities::lookup(name) {
                    // Require ; terminator or not
                    out.push_str(replacement);
                    if j < bytes.len() && bytes[j] == b';' {
                        j += 1;
                    }
                    i = j;
                    continue;
                }
            }
            out.push('&');
            i += 1;
        } else {
            // push byte(s) as char
            // Handle UTF-8 properly
            let ch_len = utf8_char_len(c);
            if i + ch_len <= bytes.len() {
                let ch_bytes = &bytes[i..i + ch_len];
                if let Ok(s) = std::str::from_utf8(ch_bytes) {
                    out.push_str(s);
                } else {
                    out.push(c as char);
                }
                i += ch_len;
            } else {
                out.push(c as char);
                i += 1;
            }
        }
    }
    out
}

fn utf8_char_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b < 0xC0 {
        1
    } else if b < 0xE0 {
        2
    } else if b < 0xF0 {
        3
    } else {
        4
    }
}
