// CSS selector parsing and matching.

use std::rc::Rc;
use crate::dom::{Node, NodeData};

#[derive(Debug, Clone)]
pub enum AttrOp {
    Exists,
    Equals(String),
    WordList(String),   // ~=
    Dash(String),       // |=
    Prefix(String),     // ^=
    Suffix(String),     // $=
    Substring(String),  // *=
}

#[derive(Debug, Clone)]
pub enum SimpleSelector {
    Type(String),   // lowercase tag, or "*" for universal
    Id(String),
    Class(String),
    Attribute(String, AttrOp),
    FirstChild,
    LastChild,
    OnlyChild,
    FirstOfType,
    LastOfType,
    OnlyOfType,
    NthChild(i32, i32),      // an + b
    NthLastChild(i32, i32),
    NthOfType(i32, i32),
    NthLastOfType(i32, i32),
    Empty,
    Root,
    Not(Vec<CompoundSelector>),
}

#[derive(Debug, Clone)]
pub struct CompoundSelector {
    pub parts: Vec<SimpleSelector>,
}

#[derive(Debug, Clone)]
pub enum Combinator {
    Descendant,
    Child,
    AdjacentSibling,
    GeneralSibling,
}

#[derive(Debug, Clone)]
pub struct ComplexSelector {
    // parts: (combinator to previous, compound)
    // First entry has combinator=Descendant (placeholder, ignored)
    pub parts: Vec<(Combinator, CompoundSelector)>,
}

pub type SelectorList = Vec<ComplexSelector>;

pub fn parse_selector_list(input: &str) -> Result<SelectorList, String> {
    let mut parser = SelectorParser::new(input);
    let list = parser.parse_selector_list()?;
    if list.is_empty() {
        return Err(format!("empty selector"));
    }
    Ok(list)
}

struct SelectorParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> SelectorParser<'a> {
    fn new(input: &'a str) -> Self {
        SelectorParser { input: input.as_bytes(), pos: 0 }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn has_ws(&self) -> bool {
        self.pos < self.input.len() && self.input[self.pos].is_ascii_whitespace()
    }

    fn parse_selector_list(&mut self) -> Result<SelectorList, String> {
        let mut list = Vec::new();
        loop {
            self.skip_ws();
            let sel = self.parse_complex_selector()?;
            list.push(sel);
            self.skip_ws();
            if self.peek() == Some(b',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        Ok(list)
    }

    fn parse_complex_selector(&mut self) -> Result<ComplexSelector, String> {
        let mut parts: Vec<(Combinator, CompoundSelector)> = Vec::new();
        self.skip_ws();
        let first = self.parse_compound()?;
        parts.push((Combinator::Descendant, first));
        loop {
            let had_ws = self.has_ws();
            self.skip_ws();
            let combinator = match self.peek() {
                Some(b'>') => {
                    self.pos += 1;
                    Combinator::Child
                }
                Some(b'+') => {
                    self.pos += 1;
                    Combinator::AdjacentSibling
                }
                Some(b'~') => {
                    self.pos += 1;
                    Combinator::GeneralSibling
                }
                Some(b',') | Some(b')') | None => break,
                _ => {
                    if had_ws {
                        Combinator::Descendant
                    } else {
                        break;
                    }
                }
            };
            self.skip_ws();
            let next = self.parse_compound()?;
            parts.push((combinator, next));
        }
        Ok(ComplexSelector { parts })
    }

    fn parse_compound(&mut self) -> Result<CompoundSelector, String> {
        let mut parts: Vec<SimpleSelector> = Vec::new();
        // Optional type selector
        match self.peek() {
            Some(b'*') => {
                self.pos += 1;
                parts.push(SimpleSelector::Type("*".to_string()));
            }
            Some(c) if is_ident_start(c) => {
                let name = self.parse_ident();
                parts.push(SimpleSelector::Type(name.to_ascii_lowercase()));
            }
            _ => {}
        }
        loop {
            match self.peek() {
                Some(b'#') => {
                    self.pos += 1;
                    let id = self.parse_ident();
                    parts.push(SimpleSelector::Id(id));
                }
                Some(b'.') => {
                    self.pos += 1;
                    let cls = self.parse_ident();
                    parts.push(SimpleSelector::Class(cls));
                }
                Some(b'[') => {
                    self.pos += 1;
                    let attr = self.parse_attr_selector()?;
                    parts.push(attr);
                }
                Some(b':') => {
                    self.pos += 1;
                    if self.peek() == Some(b':') {
                        return Err(format!("pseudo-elements not supported"));
                    }
                    let name = self.parse_ident().to_ascii_lowercase();
                    if self.peek() == Some(b'(') {
                        self.pos += 1;
                        let pseudo = self.parse_functional_pseudo(&name)?;
                        if self.peek() != Some(b')') {
                            return Err(format!("expected ) in pseudo"));
                        }
                        self.pos += 1;
                        parts.push(pseudo);
                    } else {
                        parts.push(parse_simple_pseudo(&name)?);
                    }
                }
                _ => break,
            }
        }
        if parts.is_empty() {
            return Err(format!("empty compound selector"));
        }
        Ok(CompoundSelector { parts })
    }

    fn parse_ident(&mut self) -> String {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if is_ident_char(c) {
                self.pos += 1;
            } else {
                break;
            }
        }
        String::from_utf8_lossy(&self.input[start..self.pos]).into_owned()
    }

    fn parse_attr_selector(&mut self) -> Result<SimpleSelector, String> {
        self.skip_ws();
        let name = self.parse_ident();
        if name.is_empty() {
            return Err(format!("expected attribute name"));
        }
        self.skip_ws();
        let op = match self.peek() {
            Some(b']') => {
                self.pos += 1;
                return Ok(SimpleSelector::Attribute(name, AttrOp::Exists));
            }
            Some(b'=') => {
                self.pos += 1;
                AttrOpKind::Equals
            }
            Some(b'~') if self.input.get(self.pos + 1) == Some(&b'=') => {
                self.pos += 2;
                AttrOpKind::WordList
            }
            Some(b'|') if self.input.get(self.pos + 1) == Some(&b'=') => {
                self.pos += 2;
                AttrOpKind::Dash
            }
            Some(b'^') if self.input.get(self.pos + 1) == Some(&b'=') => {
                self.pos += 2;
                AttrOpKind::Prefix
            }
            Some(b'$') if self.input.get(self.pos + 1) == Some(&b'=') => {
                self.pos += 2;
                AttrOpKind::Suffix
            }
            Some(b'*') if self.input.get(self.pos + 1) == Some(&b'=') => {
                self.pos += 2;
                AttrOpKind::Substring
            }
            _ => return Err(format!("bad attribute operator")),
        };
        self.skip_ws();
        let value = self.parse_attr_value()?;
        self.skip_ws();
        // Optionally consume 'i' or 's' flag (ignored for now)
        if let Some(c) = self.peek() {
            if c == b'i' || c == b'I' || c == b's' || c == b'S' {
                self.pos += 1;
                self.skip_ws();
            }
        }
        if self.peek() != Some(b']') {
            return Err(format!("expected ]"));
        }
        self.pos += 1;
        let op = match op {
            AttrOpKind::Equals => AttrOp::Equals(value),
            AttrOpKind::WordList => AttrOp::WordList(value),
            AttrOpKind::Dash => AttrOp::Dash(value),
            AttrOpKind::Prefix => AttrOp::Prefix(value),
            AttrOpKind::Suffix => AttrOp::Suffix(value),
            AttrOpKind::Substring => AttrOp::Substring(value),
        };
        Ok(SimpleSelector::Attribute(name, op))
    }

    fn parse_attr_value(&mut self) -> Result<String, String> {
        match self.peek() {
            Some(b'"') | Some(b'\'') => {
                let quote = self.input[self.pos];
                self.pos += 1;
                let start = self.pos;
                while self.pos < self.input.len() && self.input[self.pos] != quote {
                    self.pos += 1;
                }
                let v = String::from_utf8_lossy(&self.input[start..self.pos]).into_owned();
                if self.pos < self.input.len() {
                    self.pos += 1;
                }
                Ok(v)
            }
            _ => {
                Ok(self.parse_ident())
            }
        }
    }

    fn parse_functional_pseudo(&mut self, name: &str) -> Result<SimpleSelector, String> {
        self.skip_ws();
        match name {
            "nth-child" | "nth-last-child" | "nth-of-type" | "nth-last-of-type" => {
                let (a, b) = self.parse_nth_argument()?;
                Ok(match name {
                    "nth-child" => SimpleSelector::NthChild(a, b),
                    "nth-last-child" => SimpleSelector::NthLastChild(a, b),
                    "nth-of-type" => SimpleSelector::NthOfType(a, b),
                    "nth-last-of-type" => SimpleSelector::NthLastOfType(a, b),
                    _ => unreachable!(),
                })
            }
            "not" => {
                let list = self.parse_not_argument()?;
                Ok(SimpleSelector::Not(list))
            }
            _ => Err(format!("unsupported functional pseudo: {}", name)),
        }
    }

    fn parse_nth_argument(&mut self) -> Result<(i32, i32), String> {
        self.skip_ws();
        let start = self.pos;
        // Read until ')'
        while self.pos < self.input.len() && self.input[self.pos] != b')' {
            self.pos += 1;
        }
        let arg = String::from_utf8_lossy(&self.input[start..self.pos]);
        let arg = arg.trim().to_ascii_lowercase();
        parse_nth(&arg)
    }

    fn parse_not_argument(&mut self) -> Result<Vec<CompoundSelector>, String> {
        let mut result = Vec::new();
        loop {
            self.skip_ws();
            let c = self.parse_compound()?;
            result.push(c);
            self.skip_ws();
            if self.peek() == Some(b',') {
                self.pos += 1;
            } else {
                break;
            }
        }
        Ok(result)
    }
}

enum AttrOpKind {
    Equals,
    WordList,
    Dash,
    Prefix,
    Suffix,
    Substring,
}

fn parse_nth(arg: &str) -> Result<(i32, i32), String> {
    match arg {
        "odd" => return Ok((2, 1)),
        "even" => return Ok((2, 0)),
        _ => {}
    }
    // Formats: An+B, An, n, +n, -n, digits, +digits, -digits
    let bytes = arg.as_bytes();
    let mut pos = 0;
    // Skip whitespace
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }
    // Parse A
    let mut sign_a = 1i32;
    if pos < bytes.len() && bytes[pos] == b'+' {
        pos += 1;
    } else if pos < bytes.len() && bytes[pos] == b'-' {
        sign_a = -1;
        pos += 1;
    }
    let a_start = pos;
    while pos < bytes.len() && bytes[pos].is_ascii_digit() {
        pos += 1;
    }
    let has_n = pos < bytes.len() && bytes[pos] == b'n';
    let a: i32;
    if has_n {
        if pos == a_start {
            a = sign_a * 1;
        } else {
            let n_str = std::str::from_utf8(&bytes[a_start..pos]).unwrap();
            a = sign_a * n_str.parse::<i32>().map_err(|_| format!("invalid number"))?;
        }
        pos += 1; // consume n
    } else {
        // No n - whole thing is b
        if pos == a_start {
            return Err(format!("invalid nth"));
        }
        let n_str = std::str::from_utf8(&bytes[a_start..pos]).unwrap();
        let b_val = sign_a * n_str.parse::<i32>().map_err(|_| format!("invalid number"))?;
        return Ok((0, b_val));
    }
    // Parse optional sign + B
    let mut b = 0i32;
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }
    if pos < bytes.len() && (bytes[pos] == b'+' || bytes[pos] == b'-') {
        let sign_b = if bytes[pos] == b'-' { -1 } else { 1 };
        pos += 1;
        while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
            pos += 1;
        }
        let b_start = pos;
        while pos < bytes.len() && bytes[pos].is_ascii_digit() {
            pos += 1;
        }
        if pos == b_start {
            return Err(format!("expected number after sign in nth"));
        }
        let n_str = std::str::from_utf8(&bytes[b_start..pos]).unwrap();
        b = sign_b * n_str.parse::<i32>().map_err(|_| format!("invalid number"))?;
    }
    Ok((a, b))
}

fn parse_simple_pseudo(name: &str) -> Result<SimpleSelector, String> {
    match name {
        "first-child" => Ok(SimpleSelector::FirstChild),
        "last-child" => Ok(SimpleSelector::LastChild),
        "only-child" => Ok(SimpleSelector::OnlyChild),
        "first-of-type" => Ok(SimpleSelector::FirstOfType),
        "last-of-type" => Ok(SimpleSelector::LastOfType),
        "only-of-type" => Ok(SimpleSelector::OnlyOfType),
        "empty" => Ok(SimpleSelector::Empty),
        "root" => Ok(SimpleSelector::Root),
        _ => Err(format!("unsupported pseudo: {}", name)),
    }
}

fn is_ident_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_' || c == b'-' || c >= 0x80
}

fn is_ident_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c >= 0x80
}

// Matching

pub fn matches_selector(node: &Rc<Node>, selector: &ComplexSelector) -> bool {
    // Match from rightmost compound
    // We must match the node against the last compound, and then walk backward.
    if !node.is_element() {
        return false;
    }
    matches_complex(node, selector, selector.parts.len() - 1)
}

fn matches_complex(node: &Rc<Node>, sel: &ComplexSelector, idx: usize) -> bool {
    let (_combinator, compound) = &sel.parts[idx];
    if !matches_compound(node, compound) {
        return false;
    }
    if idx == 0 {
        return true;
    }
    let (combinator, _) = &sel.parts[idx]; // combinator to previous
    match combinator {
        Combinator::Descendant => {
            let mut cur = get_parent(node);
            while let Some(parent) = cur {
                if parent.is_element() && matches_complex(&parent, sel, idx - 1) {
                    return true;
                }
                cur = get_parent(&parent);
            }
            false
        }
        Combinator::Child => {
            if let Some(parent) = get_parent(node) {
                if parent.is_element() {
                    return matches_complex(&parent, sel, idx - 1);
                }
            }
            false
        }
        Combinator::AdjacentSibling => {
            if let Some(prev) = get_element_sibling(node, false) {
                return matches_complex(&prev, sel, idx - 1);
            }
            false
        }
        Combinator::GeneralSibling => {
            let mut cur = get_element_sibling(node, false);
            while let Some(sibling) = cur {
                if matches_complex(&sibling, sel, idx - 1) {
                    return true;
                }
                cur = get_element_sibling(&sibling, false);
            }
            false
        }
    }
}

pub fn matches_compound(node: &Rc<Node>, compound: &CompoundSelector) -> bool {
    for part in &compound.parts {
        if !matches_simple(node, part) {
            return false;
        }
    }
    true
}

fn matches_simple(node: &Rc<Node>, sel: &SimpleSelector) -> bool {
    let (tag, attrs) = match &node.data {
        NodeData::Element { name, attrs } => (name.as_str(), attrs),
        _ => return false,
    };

    match sel {
        SimpleSelector::Type(t) => t == "*" || t.eq_ignore_ascii_case(tag),
        SimpleSelector::Id(id) => {
            for (k, v) in attrs.borrow().iter() {
                if k == "id" && v == id {
                    return true;
                }
            }
            false
        }
        SimpleSelector::Class(cls) => {
            for (k, v) in attrs.borrow().iter() {
                if k == "class" {
                    for c in v.split_ascii_whitespace() {
                        if c == cls {
                            return true;
                        }
                    }
                }
            }
            false
        }
        SimpleSelector::Attribute(name, op) => {
            for (k, v) in attrs.borrow().iter() {
                if k.eq_ignore_ascii_case(name) {
                    return match op {
                        AttrOp::Exists => true,
                        AttrOp::Equals(val) => v == val,
                        AttrOp::WordList(val) => v.split_ascii_whitespace().any(|w| w == val.as_str()),
                        AttrOp::Dash(val) => v == val || v.starts_with(&format!("{}-", val)),
                        AttrOp::Prefix(val) => !val.is_empty() && v.starts_with(val.as_str()),
                        AttrOp::Suffix(val) => !val.is_empty() && v.ends_with(val.as_str()),
                        AttrOp::Substring(val) => !val.is_empty() && v.contains(val.as_str()),
                    };
                }
            }
            false
        }
        SimpleSelector::FirstChild => {
            get_element_sibling(node, false).is_none()
        }
        SimpleSelector::LastChild => {
            get_element_sibling(node, true).is_none()
        }
        SimpleSelector::OnlyChild => {
            get_element_sibling(node, false).is_none() && get_element_sibling(node, true).is_none()
        }
        SimpleSelector::FirstOfType => {
            let mut cur = get_element_sibling(node, false);
            while let Some(s) = cur {
                if s.tag_name().as_deref() == node.tag_name().as_deref() {
                    return false;
                }
                cur = get_element_sibling(&s, false);
            }
            true
        }
        SimpleSelector::LastOfType => {
            let mut cur = get_element_sibling(node, true);
            while let Some(s) = cur {
                if s.tag_name().as_deref() == node.tag_name().as_deref() {
                    return false;
                }
                cur = get_element_sibling(&s, true);
            }
            true
        }
        SimpleSelector::OnlyOfType => {
            matches_simple(node, &SimpleSelector::FirstOfType)
                && matches_simple(node, &SimpleSelector::LastOfType)
        }
        SimpleSelector::NthChild(a, b) => {
            let idx = element_index_among_siblings(node, false, None) as i32;
            match_nth(*a, *b, idx)
        }
        SimpleSelector::NthLastChild(a, b) => {
            let idx = element_index_among_siblings(node, true, None) as i32;
            match_nth(*a, *b, idx)
        }
        SimpleSelector::NthOfType(a, b) => {
            let tag = node.tag_name();
            let idx = element_index_among_siblings(node, false, tag.as_deref()) as i32;
            match_nth(*a, *b, idx)
        }
        SimpleSelector::NthLastOfType(a, b) => {
            let tag = node.tag_name();
            let idx = element_index_among_siblings(node, true, tag.as_deref()) as i32;
            match_nth(*a, *b, idx)
        }
        SimpleSelector::Empty => {
            node.children.borrow().is_empty()
        }
        SimpleSelector::Root => {
            if let Some(p) = get_parent(node) {
                matches!(p.data, NodeData::Document)
            } else {
                false
            }
        }
        SimpleSelector::Not(list) => {
            for cs in list {
                if matches_compound(node, cs) {
                    return false;
                }
            }
            true
        }
    }
}

fn match_nth(a: i32, b: i32, n: i32) -> bool {
    if a == 0 {
        n == b
    } else {
        // find non-negative k such that n = a*k + b
        let diff = n - b;
        if a == 0 {
            return diff == 0;
        }
        diff * a.signum() >= 0 && diff % a == 0
    }
}

pub fn get_parent(node: &Rc<Node>) -> Option<Rc<Node>> {
    node.parent.borrow().as_ref().and_then(|w| w.upgrade())
}

fn get_element_sibling(node: &Rc<Node>, after: bool) -> Option<Rc<Node>> {
    let parent = get_parent(node)?;
    let children = parent.children.borrow();
    let idx = children.iter().position(|n| Rc::ptr_eq(n, node))?;
    if after {
        for s in children[idx + 1..].iter() {
            if s.is_element() {
                return Some(s.clone());
            }
        }
    } else {
        for s in children[..idx].iter().rev() {
            if s.is_element() {
                return Some(s.clone());
            }
        }
    }
    None
}

fn element_index_among_siblings(node: &Rc<Node>, reverse: bool, of_type: Option<&str>) -> i32 {
    let parent = match get_parent(node) {
        Some(p) => p,
        None => return 1,
    };
    let children = parent.children.borrow();
    let elems: Vec<&Rc<Node>> = children.iter().filter(|n| {
        if !n.is_element() {
            return false;
        }
        if let Some(t) = of_type {
            return n.tag_name().as_deref() == Some(t);
        }
        true
    }).collect();
    let pos = elems.iter().position(|n| Rc::ptr_eq(n, node));
    match pos {
        Some(i) => {
            if reverse {
                (elems.len() - i) as i32
            } else {
                (i + 1) as i32
            }
        }
        None => 0,
    }
}

pub fn find_all(root: &Rc<Node>, selector: &SelectorList) -> Vec<Rc<Node>> {
    let mut result: Vec<Rc<Node>> = Vec::new();
    let mut visited: Vec<*const Node> = Vec::new();
    walk(root, &mut |n| {
        if n.is_element() {
            for sel in selector {
                if matches_selector(n, sel) {
                    let ptr = Rc::as_ptr(n);
                    if !visited.contains(&ptr) {
                        visited.push(ptr);
                        result.push(n.clone());
                    }
                    break;
                }
            }
        }
    });
    result
}

fn walk<F: FnMut(&Rc<Node>)>(node: &Rc<Node>, cb: &mut F) {
    cb(node);
    for c in node.children.borrow().iter() {
        walk(c, cb);
    }
}
