            if !is_void_element(name) {
                for c in node.children.borrow().iter() {
                    serialize(c, output);
                }
                output.push_str("</");
                output.push_str(name);
                output.push('>');
            }
        }
        NodeData::Text { content } => {
            let parent_tag = node.parent.borrow().as_ref()
                .and_then(|w| w.upgrade())
                .and_then(|p| p.tag_name());
            let raw_text = matches!(
                parent_tag.as_deref(),
                Some("script") | Some("style") | Some("xmp") | Some("iframe")
                    | Some("noembed") | Some("noframes") | Some("noscript") | Some("plaintext")
            );
            if raw_text {
                output.push_str(&content.borrow());
            } else {
                output.push_str(&escape_text(&content.borrow()));
            }
        }
        NodeData::Comment { content } => {
            output.push_str("<!--");
            output.push_str(content);
            output.push_str("-->");
        }
        NodeData::ProcessingInstruction { target, data } => {
            output.push_str("<?");
            output.push_str(target);
            output.push(' ');
            output.push_str(data);
            output.push('>');
        }
    }
}

pub fn escape_text(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '\u{A0}' => out.push_str("&nbsp;"),
            _ => out.push(c),
        }
    }
    out
}

pub fn escape_attr(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '"' => out.push_str("&quot;"),
            '\u{A0}' => out.push_str("&nbsp;"),
            _ => out.push(c),
        }
    }
    out
}

// Pretty printing support

pub fn is_inline_element(name: &str) -> bool {
    // Based on observed behavior of the original binary.
    // Everything else (including unknown) is block.
    matches!(
        name,
        "a" | "abbr" | "acronym" | "audio" | "b" | "bdi" | "bdo" | "big"
        | "button" | "canvas" | "cite" | "code" | "data" | "del" | "dfn"
        | "em" | "embed" | "i" | "iframe" | "img" | "input" | "ins" | "kbd"
        | "label" | "mark" | "meter" | "noscript" | "object" | "output"
        | "param" | "picture" | "plaintext" | "progress" | "q" | "ruby" | "s"
        | "samp" | "script" | "select" | "small" | "span" | "strong" | "sub"
        | "sup" | "svg" | "template" | "textarea" | "time" | "tt" | "u"
        | "var" | "video" | "wbr"
    )
}

pub fn pretty_serialize(node: &Rc<Node>, output: &mut String) {
    // Serialize a single node with pretty formatting.
    // Leading newline is emitted before node if element.
    pp_node(node, 0, false, output);
    output.push('\n');
}

fn pp_node(node: &Rc<Node>, indent: usize, expanded: bool, output: &mut String) {
    match &node.data {
        NodeData::Element { name, attrs } => {
            let inline = is_inline_element(name);
            if !inline || expanded {
                // Emit newline+indent before opening tag
                output.push('\n');
                for _ in 0..indent {
                    output.push(' ');
                }
            }
            output.push('<');
            output.push_str(name);
            let mut attr_list: Vec<(String, String)> = attrs.borrow().clone();
            attr_list.sort_by(|a, b| a.0.cmp(&b.0));
            for (k, v) in attr_list.iter() {
                output.push(' ');
                output.push_str(k);
                output.push('=');
                output.push('"');
                output.push_str(&escape_attr(v));
                output.push('"');
            }
            output.push('>');
            if !is_void_element(name) {
                // Children
                pp_children(node, indent + 2, expanded, output);
                // Closing
                if !inline {
                    output.push('\n');
                    for _ in 0..indent {
                        output.push(' ');
                    }
                }
                output.push_str("</");
                output.push_str(name);
                output.push('>');
            } else {
                // void: emit newline+indent for "where close would be"
                if !inline {
                    output.push('\n');
                    for _ in 0..indent {
                        output.push(' ');
                    }
                }
            }
        }
        NodeData::Text { content } => {
            let parent_tag = node.parent.borrow().as_ref()
                .and_then(|w| w.upgrade())
                .and_then(|p| p.tag_name());
            let raw_text = matches!(
                parent_tag.as_deref(),
                Some("script") | Some("style") | Some("xmp") | Some("iframe")
                    | Some("noembed") | Some("noframes") | Some("noscript") | Some("plaintext")
            );
            if expanded {
                output.push('\n');
                for _ in 0..indent {
                    output.push(' ');
                }
            }
            if raw_text {
                output.push_str(&content.borrow());
            } else {
                output.push_str(&escape_text(&content.borrow()));
            }
        }
        NodeData::Comment { content } => {
            if expanded {
                output.push('\n');
                for _ in 0..indent {
                    output.push(' ');
                }
            }
            output.push_str("<!--");
            output.push_str(content);
            output.push_str("-->");
        }
        NodeData::Document => {
            for c in node.children.borrow().iter() {
                pp_node(c, indent, false, output);
            }
        }
        NodeData::Doctype { name, .. } => {
            output.push_str("<!DOCTYPE ");
            output.push_str(name);
            output.push('>');
        }
        NodeData::ProcessingInstruction { .. } => {}
    }
}

fn pp_children(parent: &Rc<Node>, indent: usize, parent_expanded: bool, output: &mut String) {
    let children = parent.children.borrow();
    let mut prev_is_block = false;
    for (i, child) in children.iter().enumerate() {
        let child_expanded = if i == 0 {
            parent_expanded
        } else {
            prev_is_block
        };
        pp_node(child, indent, child_expanded, output);
        prev_is_block = is_node_block(child);
    }
}

fn is_node_block(node: &Rc<Node>) -> bool {
    match &node.data {
        NodeData::Element { name, .. } => !is_inline_element(name),
        _ => false,
    }
}
