// Minimal URL parsing and base-URL resolution.
// Not a full URL spec implementation but handles common cases.

#[derive(Debug, Clone, PartialEq)]
pub struct Url {
    pub scheme: String,
    pub authority: Option<String>, // includes userinfo, host, port
    pub path: String,
    pub query: Option<String>,
    pub fragment: Option<String>,
}

pub fn parse(input: &str) -> Option<Url> {
    let mut scheme = String::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    // scheme must start with letter
    if bytes.is_empty() || !bytes[0].is_ascii_alphabetic() {
        return None;
    }
    while i < bytes.len() {
        let c = bytes[i];
        if c == b':' {
            break;
        }
        if !(c.is_ascii_alphanumeric() || c == b'+' || c == b'-' || c == b'.') {
            return None;
        }
        scheme.push(c as char);
        i += 1;
    }
    if i == bytes.len() || bytes[i] != b':' || scheme.is_empty() {
        return None;
    }
    i += 1; // consume ':'
    let scheme = scheme.to_ascii_lowercase();
    let mut authority: Option<String> = None;
    let mut path = String::new();
    let mut query: Option<String> = None;
    let mut fragment: Option<String> = None;
    if bytes.len() >= i + 2 && bytes[i] == b'/' && bytes[i + 1] == b'/' {
        i += 2;
        let a_start = i;
        while i < bytes.len() {
            let c = bytes[i];
            if c == b'/' || c == b'?' || c == b'#' {
                break;
            }
            i += 1;
        }
        authority = Some(String::from_utf8_lossy(&bytes[a_start..i]).into_owned());
    }
    let p_start = i;
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'?' || c == b'#' {
            break;
        }
        i += 1;
    }
    path = String::from_utf8_lossy(&bytes[p_start..i]).into_owned();
    if i < bytes.len() && bytes[i] == b'?' {
        i += 1;
        let q_start = i;
        while i < bytes.len() && bytes[i] != b'#' {
            i += 1;
        }
        query = Some(String::from_utf8_lossy(&bytes[q_start..i]).into_owned());
    }
    if i < bytes.len() && bytes[i] == b'#' {
        i += 1;
        fragment = Some(String::from_utf8_lossy(&bytes[i..]).into_owned());
    }
    Some(Url { scheme, authority, path, query, fragment })
}

impl Url {
    pub fn to_string(&self) -> String {
        let mut out = String::new();
        out.push_str(&self.scheme);
        out.push(':');
        if let Some(a) = &self.authority {
            out.push_str("//");
            out.push_str(a);
        }
        out.push_str(&self.path);
        if let Some(q) = &self.query {
            out.push('?');
            out.push_str(q);
        }
        if let Some(f) = &self.fragment {
            out.push('#');
            out.push_str(f);
        }
        out
    }

    pub fn resolve(&self, reference: &str) -> String {
        // Implements RFC 3986 reference resolution (simplified).
        let ref_url = parse_reference(reference);
        let mut target = Url {
            scheme: String::new(),
            authority: None,
            path: String::new(),
            query: None,
            fragment: None,
        };
        if !ref_url.scheme.is_empty() {
            target.scheme = ref_url.scheme;
            target.authority = ref_url.authority;
            target.path = remove_dot_segments(&ref_url.path);
            target.query = ref_url.query;
        } else {
            if ref_url.authority.is_some() {
                target.authority = ref_url.authority;
                target.path = remove_dot_segments(&ref_url.path);
                target.query = ref_url.query;
                target.scheme = self.scheme.clone();
            } else {
                if ref_url.path.is_empty() {
                    target.path = self.path.clone();
                    if ref_url.query.is_some() {
                        target.query = ref_url.query;
                    } else {
                        target.query = self.query.clone();
                    }
                } else {
                    if ref_url.path.starts_with('/') {
                        target.path = remove_dot_segments(&ref_url.path);
                    } else {
                        let merged = merge_path(&self.path, &ref_url.path, self.authority.is_some());
                        target.path = remove_dot_segments(&merged);
                    }
                    target.query = ref_url.query;
                }
                target.authority = self.authority.clone();
                target.scheme = self.scheme.clone();
            }
        }
        target.fragment = ref_url.fragment;
        target.to_string()
    }
}

#[derive(Debug)]
struct RefUrl {
    scheme: String,
    authority: Option<String>,
    path: String,
    query: Option<String>,
    fragment: Option<String>,
}

fn parse_reference(input: &str) -> RefUrl {
    // Try full URL first
    if let Some(u) = parse(input) {
        return RefUrl {
            scheme: u.scheme,
            authority: u.authority,
            path: u.path,
            query: u.query,
            fragment: u.fragment,
        };
    }
    // Relative reference
    let bytes = input.as_bytes();
    let mut i = 0;
    let mut authority = None;
    if bytes.len() >= 2 && bytes[0] == b'/' && bytes[1] == b'/' {
        i = 2;
        let a_start = i;
        while i < bytes.len() {
            let c = bytes[i];
            if c == b'/' || c == b'?' || c == b'#' {
                break;
            }
            i += 1;
        }
        authority = Some(String::from_utf8_lossy(&bytes[a_start..i]).into_owned());
    }
    let p_start = i;
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'?' || c == b'#' {
            break;
        }
        i += 1;
    }
    let path = String::from_utf8_lossy(&bytes[p_start..i]).into_owned();
    let mut query = None;
    if i < bytes.len() && bytes[i] == b'?' {
        i += 1;
        let q_start = i;
        while i < bytes.len() && bytes[i] != b'#' {
            i += 1;
        }
        query = Some(String::from_utf8_lossy(&bytes[q_start..i]).into_owned());
    }
    let mut fragment = None;
    if i < bytes.len() && bytes[i] == b'#' {
        i += 1;
        fragment = Some(String::from_utf8_lossy(&bytes[i..]).into_owned());
    }
    RefUrl {
        scheme: String::new(),
        authority,
        path,
        query,
        fragment,
    }
}

fn merge_path(base_path: &str, ref_path: &str, has_authority: bool) -> String {
    if has_authority && base_path.is_empty() {
        format!("/{}", ref_path)
    } else {
        // Base path up to last /
        if let Some(idx) = base_path.rfind('/') {
            format!("{}{}", &base_path[..idx + 1], ref_path)
        } else {
            ref_path.to_string()
        }
    }
}

fn remove_dot_segments(path: &str) -> String {
    let mut input = path.to_string();
    let mut output = String::new();
    while !input.is_empty() {
        if input.starts_with("../") {
            input = input[3..].to_string();
        } else if input.starts_with("./") {
            input = input[2..].to_string();
        } else if input.starts_with("/./") {
            input = format!("/{}", &input[3..]);
        } else if input == "/." {
            input = "/".to_string();
        } else if input.starts_with("/../") {
            input = format!("/{}", &input[4..]);
            if let Some(idx) = output.rfind('/') {
                output.truncate(idx);
            } else {
                output.clear();
            }
        } else if input == "/.." {
            input = "/".to_string();
            if let Some(idx) = output.rfind('/') {
                output.truncate(idx);
            } else {
                output.clear();
            }
        } else if input == "." || input == ".." {
            input.clear();
        } else {
            // move first segment
            let start = if input.starts_with('/') { 1 } else { 0 };
            let end = input[start..].find('/').map(|p| p + start).unwrap_or(input.len());
            output.push_str(&input[..end]);
            input = input[end..].to_string();
        }
    }
    output
}
