// Manual clap-v2-style argument parser to match the help output and error messages.

use std::process::exit;

#[derive(Debug, Default)]
pub struct Args {
    pub detect_base: bool,
    pub ignore_whitespace: bool,
    pub pretty: bool,
    pub text: bool,
    pub attribute: Option<String>,
    pub base: Option<String>,
    pub filename: Option<String>,
    pub output: Option<String>,
    pub remove_nodes: Vec<String>,
    pub selectors: Vec<String>,
}

pub const HELP: &str = "htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    executable [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]";

pub const VERSION: &str = "htmlq 0.4.0";

pub const USAGE_HINT: &str = "USAGE:
    executable [FLAGS] [OPTIONS] [--] [selector]...

For more information try --help";

pub fn parse(argv: Vec<String>) -> Args {
    let mut args = Args::default();
    let mut i = 1;
    let mut after_double_dash = false;
    // First scan for --help, --version
    // Actually clap processes those immediately.
    while i < argv.len() {
        let a = &argv[i];
        if !after_double_dash {
            if a == "--" {
                after_double_dash = true;
                i += 1;
                continue;
            }
            if a == "-h" || a == "--help" {
                println!("{}", HELP);
                exit(0);
            }
            if a == "-V" || a == "--version" {
                println!("{}", VERSION);
                exit(0);
            }
            // Long options with = 
            if let Some(rest) = a.strip_prefix("--") {
                let (name, value) = match rest.split_once('=') {
                    Some((n, v)) => (n.to_string(), Some(v.to_string())),
                    None => (rest.to_string(), None),
                };
                match name.as_str() {
                    "detect-base" => {
                        if value.is_some() {
                            error_unexpected(a);
                        }
                        args.detect_base = true;
                        i += 1;
                        continue;
                    }
                    "ignore-whitespace" => {
                        if value.is_some() {
                            error_unexpected(a);
                        }
                        args.ignore_whitespace = true;
                        i += 1;
                        continue;
                    }
                    "pretty" => {
                        if value.is_some() {
                            error_unexpected(a);
                        }
                        args.pretty = true;
                        i += 1;
                        continue;
                    }
                    "text" => {
                        if value.is_some() {
                            error_unexpected(a);
                        }
                        args.text = true;
                        i += 1;
                        continue;
                    }
                    "attribute" => {
                        let v = match value {
                            Some(v) => v,
                            None => {
                                i += 1;
                                if i >= argv.len() {
                                    error_missing_value("--attribute");
                                }
                                argv[i].clone()
                            }
                        };
                        args.attribute = Some(v);
                        i += 1;
                        continue;
                    }
                    "base" => {
                        let v = match value {
                            Some(v) => v,
                            None => {
                                i += 1;
                                if i >= argv.len() {
                                    error_missing_value("--base");
                                }
                                argv[i].clone()
                            }
                        };
                        args.base = Some(v);
                        i += 1;
                        continue;
                    }
                    "filename" => {
                        let v = match value {
                            Some(v) => v,
                            None => {
                                i += 1;
                                if i >= argv.len() {
                                    error_missing_value("--filename");
                                }
                                argv[i].clone()
                            }
                        };
                        args.filename = Some(v);
                        i += 1;
                        continue;
                    }
                    "output" => {
                        let v = match value {
                            Some(v) => v,
                            None => {
                                i += 1;
                                if i >= argv.len() {
                                    error_missing_value("--output");
                                }
                                argv[i].clone()
                            }
                        };
                        args.output = Some(v);
                        i += 1;
                        continue;
                    }
                    "remove-nodes" => {
                        let v = match value {
                            Some(v) => v,
                            None => {
                                i += 1;
                                if i >= argv.len() {
                                    error_missing_value("--remove-nodes");
                                }
                                argv[i].clone()
                            }
                        };
                        args.remove_nodes.push(v);
                        i += 1;
                        continue;
                    }
                    _ => {
                        error_unexpected(a);
                    }
                }
            }
            if let Some(rest) = a.strip_prefix('-') {
                if !rest.is_empty() && !rest.starts_with('-') {
                    // Short flag(s)
                    let mut chars = rest.chars().peekable();
                    while let Some(c) = chars.next() {
                        match c {
                            'B' => args.detect_base = true,
                            'w' => args.ignore_whitespace = true,
                            'p' => args.pretty = true,
                            't' => args.text = true,
                            'a' | 'b' | 'f' | 'o' | 'r' => {
                                let remainder: String = chars.clone().collect();
                                let value = if !remainder.is_empty() {
                                    chars = "".chars().peekable();
                                    let stripped = remainder.strip_prefix('=').unwrap_or(&remainder);
                                    stripped.to_string()
                                } else {
                                    i += 1;
                                    if i >= argv.len() {
                                        let name = match c {
                                            'a' => "-a",
                                            'b' => "-b",
                                            'f' => "-f",
                                            'o' => "-o",
                                            'r' => "-r",
                                            _ => "",
                                        };
                                        error_missing_value(name);
                                    }
                                    argv[i].clone()
                                };
                                match c {
                                    'a' => args.attribute = Some(value),
                                    'b' => args.base = Some(value),
                                    'f' => args.filename = Some(value),
                                    'o' => args.output = Some(value),
                                    'r' => args.remove_nodes.push(value),
                                    _ => {}
                                }
                                break;
                            }
                            'h' => {
                                println!("{}", HELP);
                                exit(0);
                            }
                            'V' => {
                                println!("{}", VERSION);
                                exit(0);
                            }
                            _ => {
                                error_unexpected(&format!("-{}", c));
                            }
                        }
                    }
                    i += 1;
                    continue;
                }
            }
        }
        args.selectors.push(a.clone());
        i += 1;
    }
    args
}

fn error_unexpected(arg: &str) -> ! {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    eprintln!();
    eprintln!("{}", USAGE_HINT);
    exit(1);
}

fn error_missing_value(opt: &str) -> ! {
    eprintln!("error: The argument '{}' requires a value but none was supplied", opt);
    eprintln!();
    eprintln!("{}", USAGE_HINT);
    exit(1);
