// Manual clap-v2-style argument parser to match the help output and error messages.

use std::process::exit;

#[derive(Debug, Default)]
pub struct Args {
    pub detect_base: bool,
    pub ignore_whitespace: bool,
    pub pretty: bool,
    pub text: bool,
    pub attribute: Option<String>,
    pub base: Option<String>,
    pub filename: Option<String>,
    pub output: Option<String>,
    pub remove_nodes: Vec<String>,
    pub selectors: Vec<String>,
}

pub const HELP: &str = "htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    executable [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]";

pub const VERSION: &str = "htmlq 0.4.0";

const GENERAL_USAGE: &str = "    executable [FLAGS] [OPTIONS] [--] [selector]...";

fn opt_usage(opt: &str) -> &'static str {
    match opt {
        "-a" | "--attribute" => "    executable --attribute <attribute>",
        "-b" | "--base" => "    executable --base <base>",
        "-f" | "--filename" => "    executable --filename <FILE>",
        "-o" | "--output" => "    executable --output <FILE>",
        "-r" | "--remove-nodes" => "    executable --remove-nodes <SELECTOR>...",
        _ => GENERAL_USAGE,
    }
}

fn opt_display(opt: &str) -> &'static str {
    match opt {
        "-a" | "--attribute" => "--attribute <attribute>",
        "-b" | "--base" => "--base <base>",
        "-f" | "--filename" => "--filename <FILE>",
        "-o" | "--output" => "--output <FILE>",
        "-r" | "--remove-nodes" => "--remove-nodes <SELECTOR>...",
        _ => opt,
    }
}

fn error_unexpected(arg: &str, usage: &str) -> ! {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("{}", usage);
    eprintln!();
    eprintln!("For more information try --help");
    exit(1);
}

fn error_missing(opt: &str) -> ! {
    eprintln!("error: The argument '{}' requires a value but none was supplied", opt_display(opt));
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("{}", opt_usage(opt));
    eprintln!();
    eprintln!("For more information try --help");
    exit(1);
}

pub fn parse(argv: Vec<String>) -> Args {
    let mut args = Args::default();
    let mut i = 1;
    let mut after_double_dash = false;
    // Track processed flags for error usage display
    let mut flag_ctx: Vec<&'static str> = Vec::new();

    while i < argv.len() {
        let a = argv[i].clone();
        if !after_double_dash {
            if a == "--" {
                after_double_dash = true;
                i += 1;
                continue;
            }
            if a == "-h" || a == "--help" {
                println!("{}", HELP);
                exit(0);
            }
            if a == "-V" || a == "--version" {
                println!("{}", VERSION);
                exit(0);
            }
            if let Some(rest) = a.strip_prefix("--") {
                // Long option
                let (name, value) = match rest.split_once('=') {
                    Some((n, v)) => (n.to_string(), Some(v.to_string())),
                    None => (rest.to_string(), None),
                };
                let flag_key = match name.as_str() {
                    "detect-base" => { if value.is_some() { error_unexpected(&a, GENERAL_USAGE) } args.detect_base = true; i += 1; continue; }
                    "ignore-whitespace" => { if value.is_some() { error_unexpected(&a, GENERAL_USAGE) } args.ignore_whitespace = true; i += 1; continue; }
                    "pretty" => { if value.is_some() { error_unexpected(&a, GENERAL_USAGE) } args.pretty = true; i += 1; continue; }
                    "text" => { if value.is_some() { error_unexpected(&a, GENERAL_USAGE) } args.text = true; i += 1; continue; }
                    "attribute" => "-a",
                    "base" => "-b",
                    "filename" => "-f",
                    "output" => "-o",
                    "remove-nodes" => "-r",
                    _ => error_unexpected(&a, GENERAL_USAGE),
                };
                let opt_long = format!("--{}", name);
                let v = match value {
                    Some(v) => v,
                    None => {
                        i += 1;
                        if i >= argv.len() {
                            error_missing(flag_key);
                        }
                        argv[i].clone()
                    }
                };
                match flag_key {
                    "-a" => args.attribute = Some(v),
                    "-b" => args.base = Some(v),
                    "-f" => args.filename = Some(v),
                    "-o" => args.output = Some(v),
                    "-r" => args.remove_nodes.push(v),
                    _ => {}
                }
                let _ = opt_long; // unused
                i += 1;
                continue;
            }
            if a.starts_with('-') && a.len() > 1 {
                // Short flags
                let chars: Vec<char> = a[1..].chars().collect();
                let mut ci = 0;
                while ci < chars.len() {
                    let c = chars[ci];
                    match c {
                        'B' => { flag_ctx.push("--detect-base"); args.detect_base = true; ci += 1; }
                        'w' => { flag_ctx.push("--ignore-whitespace"); args.ignore_whitespace = true; ci += 1; }
                        'p' => { flag_ctx.push("--pretty"); args.pretty = true; ci += 1; }
                        't' => { flag_ctx.push("--text"); args.text = true; ci += 1; }
                        'a' | 'b' | 'f' | 'o' | 'r' => {
                            flag_ctx.push(match c {
                                'a' => "--attribute",
                                'b' => "--base",
                                'f' => "--filename",
                                'o' => "--output",
                                'r' => "--remove-nodes",
                                _ => "",
                            });
                            let key = match c {
                                'a' => "-a",
                                'b' => "-b",
                                'f' => "-f",
                                'o' => "-o",
                                'r' => "-r",
                                _ => "",
                            };
                            ci += 1;
                            let remaining: String = chars[ci..].iter().collect();
                            let v = if !remaining.is_empty() {
                                let stripped = remaining.strip_prefix('=').unwrap_or(&remaining);
                                stripped.to_string()
                            } else {
                                i += 1;
                                if i >= argv.len() {
                                    error_missing(key);
                                }
                                argv[i].clone()
                            };
                            match c {
                                'a' => args.attribute = Some(v),
                                'b' => args.base = Some(v),
                                'f' => args.filename = Some(v),
                                'o' => args.output = Some(v),
                                'r' => args.remove_nodes.push(v),
                                _ => {}
                            }
                            ci = chars.len(); // consume rest
                        }
                        'h' => {
                            println!("{}", HELP);
                            exit(0);
                        }
                        'V' => {
                            println!("{}", VERSION);
                            exit(0);
                        }
                        _ => {
                            // unexpected: use the ctx USAGE
                            let usage_str = if flag_ctx.is_empty() {
                                GENERAL_USAGE.to_string()
                            } else {
                                format!("    executable {}", flag_ctx.join(" "))
                            };
                            error_unexpected(&format!("-{}", c), &usage_str);
                        }
                    }
                }
                i += 1;
                continue;
            }
        }
        args.selectors.push(a);
        i += 1;
    }
    args
}
EOF
