new = '''        // Determine where to insert text.
        let parent: Rc<Node>;
        let mut to_insert = text.clone();
        if let Some(top) = self.open_stack.last() {
            let top_name = top.tag_name().unwrap_or_default();
            if top_name == "html" {
                if !self.head_closed {
                    if to_insert.chars().all(|c| c.is_ascii_whitespace()) {
                        // Skip whitespace in "before head" mode
                        return;
                    }
                    // Non-whitespace: close head and move to body
                    self.head_closed = true;
                    if self.head_elem.is_none() {
                        let head = Node::new(NodeData::Element {
                            name: "head".to_string(),
                            attrs: RefCell::new(Vec::new()),
                        });
                        Node::append(self.html_elem.as_ref().unwrap(), head.clone());
                        self.head_elem = Some(head);
                    }
                    self.open_stack.retain(|n| n.tag_name().as_deref() != Some("head"));
                }
                // In "after head" mode: split leading whitespace to html scope.
                if self.body_elem.is_none() {
                    let ws_end = to_insert
                        .chars()
                        .take_while(|c| c.is_ascii_whitespace())
                        .map(|c| c.len_utf8())
                        .sum::<usize>();
                    if ws_end > 0 {
                        let ws = to_insert[..ws_end].to_string();
                        let html = self.html_elem.clone().unwrap();
                        // merge with previous text child of html if exists
                        let merged = {
                            let children = html.children.borrow();
                            let last_opt = children.last().cloned();
                            if let Some(last) = last_opt {
                                if let NodeData::Text { content } = &last.data {
                                    content.borrow_mut().push_str(&ws);
                                    true
                                } else {
                                    false
                                }
                            } else {
                                false
                            }
                        };
                        if !merged {
                            Node::append(&html, Node::new(NodeData::Text {
                                content: RefCell::new(ws),
                            }));
                        }
                        to_insert = to_insert[ws_end..].to_string();
                    }
                    if to_insert.is_empty() {
                        return;
                    }
                }
                self.ensure_body();
                parent = self.body_elem.clone().unwrap();
            } else {
                parent = top.clone();
            }
        } else {
            if let Some(body) = &self.body_elem {
                parent = body.clone();
            } else {
                if to_insert.chars().all(|c| c.is_ascii_whitespace()) {
                    return;
                }
                self.ensure_html();
                if self.head_elem.is_none() {
                    let head = Node::new(NodeData::Element {
                        name: "head".to_string(),
                        attrs: RefCell::new(Vec::new()),
                    });
                    Node::append(self.html_elem.as_ref().unwrap(), head.clone());
                    self.head_elem = Some(head);
                }
                self.head_closed = true;
                self.ensure_body();
                parent = self.body_elem.clone().unwrap();
            }
        }
        let text = to_insert;'''
